[step 1] shell "python - <<'EOF'
import csv, re, json
inv = {}
with open('backoffice/invoices.csv', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        inv[row['id']] = {'amount': float(row['amount']), 'customer': row['customer']}
pays = {}
with open('backoffice/bank_statement_june.csv', encoding='utf-8') as f:
    for row in csv.DictReader(f):
        memo = row['memo']; amt = float(row['amount'])
        if 'unidentified' in memo.lower() or 'interest' in memo.lower() or 'fee' in memo.lower():
            continue
        m = re.search(r'(?:INV-?|invoice\s*|inv)\s*(\d{4})', memo, re.I)
        if not m:
            print('NO MATCH:', memo); continue
        iid = 'INV-' + m.group(1)
        pays.setdefault(iid, []).append(amt)

# check extra ids not in invoices
for k in pays:
    if k not in inv: print('UNKNOWN INVOICE:', k)

unpaid, duplicated, mismatched = [], [], []
for iid, data in inv.items():
    ps = pays.get(iid, [])
    if not ps:
        unpaid.append(iid)
    elif len(ps) > 1:
        duplicated.append(iid)
    else:
        if abs(ps[0] - data['amount']) > 0.001:
            mismatched.append({'id': iid, 'invoiced': data['amount'], 'paid': ps[0]})

result = {'unpaid': sorted(unpaid), 'duplicated': sorted(duplicated), 'mismatched': sorted(mismatched, key=lambda x: x['id'])}
print(json.dumps(result, indent=2))
with open('result.json','w',encoding='utf-8') as f:
    json.dump(result, f, indent=2)
